pub trait WorkAdmissionPort {
    fn submit(&self, request: &crate::work_requests::SubmitRequest)
        -> Result<crate::work_types::ControlOutcome, crate::work_error::WorkError>;
    fn cancel(&self, request: &crate::work_requests::CancelRequest)
        -> Result<crate::work_types::ControlOutcome, crate::work_error::WorkError>;
    fn accept(&self, request: &crate::work_requests::AcceptRequest)
        -> Result<crate::work_types::ControlOutcome, crate::work_error::WorkError>;
    fn resume(&self, request: &crate::work_requests::ResumeRequest)
        -> Result<crate::work_types::ControlOutcome, crate::work_error::WorkError>;
    fn policy_identity(&self, project_alias: &str, kind: &str,
        snapshot: &serde_json::Value)
        -> Result<crate::work_types::PolicyIdentity, crate::work_error::WorkError>;
    fn policy_drifted(&self, workflow_id: uuid::Uuid,
        snapshot: &serde_json::Value)
        -> Result<bool, crate::work_error::WorkError>;
}
